public static class TerminalCommands {
 // Shell sources must use LF. A CR after PS1='...' is a literal part of PS1,
 // so bash prints the prompt and then returns the cursor to column zero.
 internal static string ShellScript(string script){return (script??"").Replace("\r\n","\n").Replace("\r","\n");}

 public static string Sh(string value){return "'"+(value??"").Replace("'","'\"'\"'")+"'";}
 public static string Build(Server server,string directory){
 if(server.IsLocal){string script="$OutputEncoding = [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding; [Console]::InputEncoding = [Console]::OutputEncoding; "+(string.IsNullOrEmpty(directory)?"":"Set-Location -LiteralPath '"+directory.Replace("'","''")+"'; ")+@"
function global:prompt {
 $aqenv=''; if ($env:CONDA_PREFIX) {$aqenv=$env:CONDA_DEFAULT_ENV} elseif ($env:VIRTUAL_ENV) {$aqenv=Split-Path $env:VIRTUAL_ENV -Leaf}
 $aqstate=$env:USERNAME+""`n""+$env:COMPUTERNAME+""`n""+$PWD.Path+""`nPowerShell`n""+$aqenv
 [Console]::Write(([char]27).ToString()+']1337;AQSTATUS='+[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($aqstate))+[char]7)
 $(if($aqenv){'('+$aqenv+') '})+$env:USERNAME+'@'+$env:COMPUTERNAME+':'+$PWD.Path+'> '
}
";return ConPtySession.Quote(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe"))+" -NoLogo -NoExit -ExecutionPolicy Bypass -EncodedCommand "+Convert.ToBase64String(Encoding.Unicode.GetBytes(script));}
 if(string.IsNullOrWhiteSpace(server.Host)||server.Host.StartsWith("-",StringComparison.Ordinal)||server.Host.IndexOfAny(new[]{'\r','\n','\0','"'})>=0)throw new ArgumentException("服务器主机名无效");
 string bootstrap=ShellScript(File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"TerminalAssets","bootstrap.sh")))+ (string.IsNullOrEmpty(directory)?"":"\ncd -- "+Sh(directory)+"\n");
 string encoded=Convert.ToBase64String(Encoding.UTF8.GetBytes(bootstrap));string command="exec bash --rcfile <(printf %s "+Sh(encoded)+" | base64 -d) -i";
 return ConPtySession.Quote(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"OpenSSH\ssh.exe"))+" -tt -o ServerAliveInterval=30 -o ServerAliveCountMax=3 -p "+server.Port+(string.IsNullOrWhiteSpace(server.User)?"":" -l "+ConPtySession.Quote(server.User))+(string.IsNullOrWhiteSpace(server.KeyPath)?"":" -i "+ConPtySession.Quote(server.KeyPath))+" "+ConPtySession.Quote(server.Host)+" "+ConPtySession.Quote("bash -lc "+Sh(command));
 }
}





